  parameters: {
    docs: {
      description: { story: "Omit `onValueChange` and the steps render as plain elements. Use it for questionnaires and wizards where only Next and Back move the user, and set an `aria-label` that names the position." },
      source: { code: ReadOnlySource },
    },
  },
  render: ReadOnlyExample,
};

export const Blocked: Story = {
  parameters: {
    docs: {
      description: { story: "Set `reach` to the furthest step the user has earned. Dots after it are blocked while earlier dots stay clickable. Use `disabled` on an item for rules that are not linear, or refuse the change inside `onValueChange` when blocking depends on validation." },
      source: { code: BlockedSource },
    },
  },
  render: BlockedExample,
};

export const Status: Story = {
  parameters: {
    docs: {
      description: { story: "Render `StepIndicatorItem` children to give each step a `label`, mark it `invalid`, or `disabled`. Override `status` when completion is not simply "everything before the current step"." },
      source: { code: StatusSource },
    },
  },
  render: StatusExample,
};

export const Progress: Story = {
  parameters: {
    docs: {
      description: { story: "`progress` (0 to 1) fills the current pill. Drive it from anything: a timer for a carousel, upload progress, or the fraction of answered fields in the step." },
      source: { code: ProgressSource },
    },
  },
  render: ProgressExample,
};

export const Vertical: Story = {
  parameters: {
    docs: {
      description: { story: "Set `orientation="vertical"` for side rails and compact lists." },
      source: { code: VerticalSource },
    },
  },
  render: VerticalExample,
};

export const Tabs: Story = {
  parameters: {
    docs: {
      description: { story: "The indicator and Tabs share one index. Tabs own the content and keyboard behavior; the indicator is a second, compact control for the same state." },
      source: { code: TabsSource },
    },
  },
  render: TabsExample,
};

export const TanstackForm: Story = {
  parameters: {
    docs: {
      description: { story: "Keep the step in React state and the values in TanStack Form. One Effect Schema describes the whole form; each step validates its field with the matching `Schema.toStandardSchemaV1(Signup.fields.name)` validator.

- **Mount every field.** `form.validateField` only finds validators on mounted fields, so an unmounted step would pass validation unchecked. Render all steps and hide the inactive ones with `field.TextField`'s `hidden`.
- **Validate only what the user passes.** `goTo` validates each step on the way forward, which also marks it touched, and stops at the first invalid one. Steps ahead are never validated, so they never show an error before the user reaches them.
- **Gate errors on `isTouched`.** The step's `invalid` uses `isTouched && !isValid`; the bound field shows its error under the same rule.
- **Submit validates everything.** `onSubmitInvalid` sends the user to the first failing step.
- Going back is always free." },
      source: { code: TanstackFormSource },
    },
  },
  render: TanstackFormExample,
};

