const Required = Schema.Trim.check(Schema.isNonEmpty({ message: "Required" }));

const Signup = Schema.Struct({
  company: Required,
  email: Schema.String.check(
    Schema.isPattern(/^[^\s@]+@[^\s@]+\.[^\s@]+$/u, { message: "Enter a valid email address." }),
